-- Publish a corrected questionnaire without rewriting any submitted attempt.
-- Materials, images and event date are copied from the existing training.
begin;
do $revision$
declare v_old public.partner_training_events; v_new_id uuid; v_admin uuid; v_materials jsonb; v_event jsonb;
begin
 select * into strict v_old from public.partner_training_events where id='218c2ad0-06d2-4d58-890b-e3253991c57f' for update;
 if exists(select 1 from public.partner_training_events where partner_company_id=v_old.partner_company_id and training_date=v_old.training_date and title='Treinamento Garmin · Duty Free · questionário revisado') then raise exception 'A revised version already exists; inspect it before running again.'; end if;
 select p.id into strict v_admin from public.profiles p join public.roles r on r.id=p.role_id where r.code='admin' limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'title',title,'source_id',source_id,'payload',payload,'url',url,'order_index',order_index) order by order_index,id),'[]') into v_materials from public.partner_training_materials where event_id=v_old.id;
 v_event:=to_jsonb(v_old)-'id'-'created_at'-'updated_at';
 v_event:=v_event||jsonb_build_object('title','Treinamento Garmin · Duty Free · questionário revisado','is_published',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v_admin,'role','authenticated')::text,true);
 v_new_id:=public.fn_save_partner_training(v_event,'[{"question_text":"O cliente ainda não explicou como pretende usar o Garmin. Qual pergunta identifica a atividade que vai orientar a indicação?","options_json":["“Qual faixa de preço você pretende considerar na compra?”","“Você quer usar em quais atividades e o que gostaria de acompanhar?”","“Qual tamanho de caixa você prefere experimentar no pulso?”"],"correct_option":1,"order_index":0},{"question_text":"Qual linha da Garmin tem como foco principal a corrida e o acompanhamento da evolução nos treinos?","options_json":["Forerunner.","Instinct.","Venu."],"correct_option":0,"order_index":1},{"question_text":"O cliente quer correr ouvindo música em fones Bluetooth, sem levar o celular. Qual função precisa existir no relógio para isso?","options_json":["Controle das músicas que estão tocando no celular.","Exibição das notificações do aplicativo de música do celular.","Armazenamento e reprodução de música no próprio relógio."],"correct_option":2,"order_index":2},{"question_text":"Ao registrar uma corrida ao ar livre com o GPS integrado do Garmin, qual é o papel do celular?","options_json":["Ele precisa acompanhar o cliente para medir a distância que aparece no relógio.","Ele pode ficar em casa: o relógio registra a atividade e a sincronização acontece depois.","Ele precisa enviar a localização por Bluetooth para o relógio gravar o trajeto."],"correct_option":1,"order_index":3},{"question_text":"Um Garmin sem conexão de dados própria recebe notificações do telefone por Bluetooth. Para continuar recebendo essas notificações durante a caminhada, o que precisa acontecer?","options_json":["O telefone deve estar ligado e com internet, mesmo que fique em casa fora do alcance do relógio.","O relógio deve ter sincronizado as notificações no Garmin Connect antes de sair de casa.","O telefone deve acompanhar o cliente, dentro do alcance do Bluetooth, com as permissões de notificações ativadas."],"correct_option":2,"order_index":4},{"question_text":"O cliente viu “tela AMOLED” na descrição. A que característica esse termo se refere?","options_json":["À tecnologia da tela, com cores vivas e alto contraste.","À forma de navegação, feita por toques em vez de botões.","À função solar, que aproveita a luz para recarregar a bateria."],"correct_option":0,"order_index":5},{"question_text":"O cliente quer testar se consegue usar os comandos do próprio relógio. Qual demonstração permite verificar isso na loja?","options_json":["Mostrar no celular do vendedor o histórico de uma atividade no Garmin Connect.","Pedir que o cliente abra uma atividade no relógio e depois volte à tela inicial, com orientação.","Apresentar as diferenças de sensores e autonomia entre dois modelos da vitrine."],"correct_option":1,"order_index":6},{"question_text":"Na compra de um Garmin para presente, qual informação permite relacionar os recursos esportivos ao uso de quem vai recebê-lo?","options_json":["As atividades que essa pessoa pratica e o que deseja acompanhar nelas.","As cores e os materiais de pulseira disponíveis para entrega na loja.","A faixa de investimento e a condição de pagamento preferida por quem compra."],"correct_option":0,"order_index":7},{"question_text":"Ao apresentar a autonomia de bateria de um Garmin, qual orientação está correta?","options_json":["A duração em modo smartwatch também vale para um treino com GPS ligado durante todo esse período.","O número de dias em modo smartwatch permanece igual quando a tela fica sempre acesa e o GPS registra treinos.","A duração depende do modelo e das configurações; GPS e tela sempre acesa podem reduzir a autonomia."],"correct_option":2,"order_index":8},{"question_text":"O cliente está inseguro com a quantidade de recursos. Para começar a registrar as atividades que ele pratica, qual orientação está correta?","options_json":["É necessário configurar os campos de dados de todos os esportes disponíveis antes de registrar a primeira atividade.","O primeiro passo obrigatório é aprender a iniciar as atividades pelo aplicativo do celular, em vez dos comandos do relógio.","É possível começar pelas funções básicas e pelas atividades que ele usa, aprendendo os outros recursos depois."],"correct_option":2,"order_index":9}]'::jsonb,v_materials);
 -- Keep ongoing respondents able to finish their original questionnaire.
 update public.partner_training_events set title='Treinamento Garmin · Duty Free · versão anterior',updated_at=now() where id=v_old.id;
end $revision$;
commit;
